using System.Reflection;using TownOfHost;
partial class Program {
static void WaitFetch()=>Check(SpinWait.SpinUntil(()=>(int)typeof(StreamerInfo).GetField("fetching",flags).GetValue(null)==0,5000),"fetch did not stop");
static void StartFetch(){TownOfHost.Main.ShowStreamComments.Value=true;StreamerInfo.CommentFrameTick(.02f);WaitFetch();}
static void RunCommentFix(){
foreach(var reason in Enum.GetValues<YouTubeFailure>().Where(x=>x!=YouTubeFailure.NetworkInterrupted))Test("terminal reason stops without per-frame retries "+reason,()=>{ResetStream();var(i,h)=FakeStream();h.Failure=reason;StartFetch();for(int n=0;n<100;n++)StreamerInfo.CommentFrameTick(.02f);Check(h.Calls==1&&StreamerInfo.HasConnectionError&&StreamerInfo.Status.ToString()==reason.ToString());Check(FrameTextUnderTest.BuildText().Contains("YouTube"));});
Test("actual formatter safely renders Japanese and English",()=>{ResetStream();var(i,h)=FakeStream();Queue(i,"1","a","<b>日本語😀</b>");Queue(i,"2","b","English");Drain();var s=FrameTextUnderTest.BuildText();Check(s.Contains("＜b＞日本語😀＜/b＞")&&s.Contains("English")&&s.Contains("YouTube ライブチャット"));});
Test("worker status changes independent of comments",()=>{ResetStream();int before=StreamerInfo.StatusVersion;var(i,h)=FakeStream();h.Failure=YouTubeFailure.InvalidResponse;StartFetch();Check(StreamerInfo.StatusVersion>before&&StreamerInfo.RecentComments.Count==0);});
Test("fixed diagnostics contain no exception data or identity",()=>{ResetStream();var(i,h)=FakeStream();h.Failure=YouTubeFailure.PermissionDenied;StartFetch();Check(TownOfHost.Logger.Logs.Count==1);foreach(var log in TownOfHost.Logger.Logs)foreach(var bad in new[]{"https://","AbCdef12_-3","token","viewer"})Check(!log.Contains(bad));});
Test("explicit stop cancels without error noise",()=>{ResetStream();var(i,h)=FakeStream();h.Hang=true;TownOfHost.Main.ShowStreamComments.Value=true;StreamerInfo.CommentFrameTick(.02f);Check(SpinWait.SpinUntil(()=>h.Calls==1,2000));StreamerInfo.StopNetwork();WaitFetch();Check(StreamerInfo.Status==StreamerInfo.ConnectionStatus.Paused&&TownOfHost.Logger.Warnings.Count==0);});
Test("policy pending prevents real intake while preserving display",()=>{ResetStream();YouTubeOfficialRuntime.ParticipationPolicyReviewed=false;StreamerInfo.StartInterestReception();var(i,h)=FakeStream();Queue(i,"1","a","join:");Drain();Check(!StreamerInfo.Interests.Accepting&&StreamerInfo.Interests.Count==0&&StreamerInfo.RecentComments.Count==1);});
Test("network retry is delayed and cancellation interrupts wait",()=>{ResetStream();var(i,h)=FakeStream();h.Failure=YouTubeFailure.NetworkInterrupted;TownOfHost.Main.ShowStreamComments.Value=true;StreamerInfo.CommentFrameTick(.02f);Check(SpinWait.SpinUntil(()=>StreamerInfo.Status==StreamerInfo.ConnectionStatus.NetworkError,2000));for(int n=0;n<100;n++)StreamerInfo.CommentFrameTick(.02f);Check(h.Calls==1);StreamerInfo.StopNetwork();WaitFetch();});
Test("revoked auth clears comments and interest data on main thread",()=>{ResetStream();StreamerInfo.StartInterestReception();var(i,h)=FakeStream();Queue(i,"personal","a","join:");Drain();Check(StreamerInfo.Interests.Count==1);h.Failure=YouTubeFailure.AuthenticationExpired;StartFetch();Drain();Check(StreamerInfo.Interests.Count==0&&!StreamerInfo.Interests.Accepting&&StreamerInfo.RecentComments.Count==0);});
Test("planned stream renewal is not counted as a network failure",()=>{ResetStream();var(i,h)=FakeStream();h.RotateOnce=true;h.Hang=true;TownOfHost.Main.ShowStreamComments.Value=true;StreamerInfo.CommentFrameTick(.02f);Check(SpinWait.SpinUntil(()=>h.Calls==2,7000));StreamerInfo.StopNetwork();WaitFetch();Check(TownOfHost.Logger.Warnings.Count==0);});
Test("persistent network failure stops after four bounded attempts",()=>{ResetStream();var(i,h)=FakeStream();h.Failure=YouTubeFailure.NetworkInterrupted;TownOfHost.Main.ShowStreamComments.Value=true;StreamerInfo.CommentFrameTick(.02f);Check(SpinWait.SpinUntil(()=>(int)typeof(StreamerInfo).GetField("fetching",flags).GetValue(null)==0,45000),"bounded retries did not finish");for(int n=0;n<100;n++)StreamerInfo.CommentFrameTick(.02f);Check(h.Calls==4&&TownOfHost.Logger.Warnings.Count==4&&StreamerInfo.Status==StreamerInfo.ConnectionStatus.NetworkError);});
Test("default missing authentication makes zero HTTP requests",()=>{ResetStream();TownOfHost.Main.ShowStreamComments.Value=true;StreamerInfo.CommentFrameTick(.02f);WaitFetch();Check(StreamerInfo.Status==StreamerInfo.ConnectionStatus.MissingCredentials);});
StreamerInfo.DisconnectInternal();}
}
